public int calculate(String s) {
    Deque<Integer> stack = new ArrayDeque<>();
    int result = 0;     // running total at the current level
    int number = 0;     // number currently being built
    int sign = 1;       // +1 or -1, applies to `number`

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (Character.isDigit(c)) {
            number = number * 10 + (c - '0');
        } else if (c == '+') {
            result += sign * number;
            number = 0;
            sign = 1;
        } else if (c == '-') {
            result += sign * number;
            number = 0;
            sign = -1;
        } else if (c == '(') {
            stack.push(result);   // save outer result
            stack.push(sign);     // save outer sign
            result = 0;
            sign = 1;
        } else if (c == ')') {
            result += sign * number;       // fold the last inner number
            number = 0;
            result *= stack.pop();         // multiply by sign before '('
            result += stack.pop();         // add result before '('
        }
        // spaces fall through and are ignored
    }
    return result + sign * number;         // trailing number
}

